/**
 * Shared data contracts between the build pipeline (scripts/) and the web app (src/).
 *
 * Everything under public/data/ is generated by `npm run data:build` and conforms to
 * these types. See docs/DATA_FORMAT.md for the on-disk layout and worked examples.
 *
 * Versification: every file is keyed by ENGLISH versification as used by the BSB
 * (which matches KJV/WEB/ASV/YLT for nearly all verses). Where the Hebrew/Greek
 * source numbers a verse differently (e.g. English Mal 4:1 = Hebrew Mal 3:19,
 * Psalm titles), original-language words are re-keyed to the English verse they
 * are translated in, and keep their source reference in OrigWord[OW.ref].
 */

/** USFM-style book code, e.g. "GEN", "PSA", "JHN", "1CO", "REV". */
export type BookId = string;

export interface BookMeta {
  /** USFM code, e.g. "JHN". */
  id: BookId;
  /** 1-based canonical position (Genesis = 1, Revelation = 66). */
  num: number;
  /** Display name, e.g. "John", "1 Corinthians". */
  name: string;
  /** Short display label for tight UI, e.g. "Jn", "1 Cor". */
  short: string;
  testament: 'OT' | 'NT';
  /** Number of verses in each chapter (index 0 = chapter 1), English versification. */
  verses: number[];
}

export type AlignmentKind =
  /** Hand-made word alignment (Clear-Bible / Biblica, CC BY 4.0). */
  | 'manual'
  /** Each English word carries Strong's numbers from the translation's own tagging (KJV). */
  | 'strongs'
  /** Automatic: aligned by bridging through the BSB's manual alignment (approximate). */
  | 'bridged'
  /** No word-level alignment available. */
  | 'none';

export interface TranslationMeta {
  /** Stable id used in URLs and file paths, e.g. "BSB". */
  id: string;
  /** Full name, e.g. "Berean Standard Bible". */
  name: string;
  /** Short label for chips/tabs, e.g. "BSB". */
  abbr: string;
  year: string;
  /** Licence statement shown in the UI, e.g. "Public domain". */
  license: string;
  alignment: AlignmentKind;
  /** One or two sentences describing the translation's style. */
  description: string;
  /** Where the text came from (URL or project name). */
  source: string;
  /** True for translations fetched at runtime from a user-configured API (e.g. NIV via API.Bible). */
  remote?: boolean;
}

/** public/data/meta.json */
export interface DataMeta {
  /** Bumped whenever the data format changes; the app uses it to bust caches. */
  version: string;
  /** ISO date the data was generated. */
  generated: string;
  translations: TranslationMeta[];
  books: BookMeta[];
  /** Credits for every dataset used, shown on the About page. */
  credits: { name: string; license: string; url: string; note?: string }[];
}

/* ------------------------------------------------------------------------ */
/* Original-language words: public/data/orig/{BOOK}/{CHAPTER}.json          */
/* ------------------------------------------------------------------------ */

/**
 * One original-language word (Greek) or morpheme (Hebrew prefixes, roots and
 * suffixes are separate entries so that "and" / "the" / "in" can link to the
 * exact prefix). Stored as a tuple to keep the files small; use the OW index
 * constants (or helpers in src/lib/data.ts) to read fields.
 */
export type OrigWord = [
  /** OW.text: surface form as printed (Greek with accents; Hebrew pointed, no cantillation). */
  text: string,
  /** OW.strongs: normalised Strong's id: "G0025", "H7225", or extended "H0871a". "" if none. */
  strongs: string,
  /** OW.lemma: dictionary form. */
  lemma: string,
  /** OW.morph: Robinson code for Greek ("V-AAI-3S"), OSHB-style code for Hebrew ("Vqp3ms"), or "". */
  morph: string,
  /** OW.gloss: short contextual English gloss. */
  gloss: string,
  /** OW.verse: English verse number (within this English chapter) this word is translated in. */
  verse: number,
  /** OW.ref: source reference when it differs from the English one, e.g. "3:19"; otherwise "". */
  ref: string,
  /** OW.group: index (in this chapter's `words`) of the first morpheme of the same written word. Greek: own index. */
  group: number,
  /** OW.translit: transliteration of this word/morpheme ("" if not available; the app can generate Greek). */
  translit: string,
  /** OW.lxx: OT only — Septuagint-equivalent Greek form and Strong's, "ἐποίησεν|G4160", or "". */
  lxx: string,
];

export const OW = {
  text: 0,
  strongs: 1,
  lemma: 2,
  morph: 3,
  gloss: 4,
  verse: 5,
  ref: 6,
  group: 7,
  translit: 8,
  lxx: 9,
} as const;

export interface OrigChapter {
  book: BookId;
  /** English chapter number. */
  chapter: number;
  /** "grc" = Koine Greek (NT, SBLGNT); "hbo" = Biblical Hebrew (OT, WLC). Aramaic words are flagged per word via `aramaic`. */
  lang: 'grc' | 'hbo';
  /** Source edition id, e.g. "SBLGNT" or "WLC". */
  edition: string;
  /** All words in source order. Token links in TextChapter index into this array. */
  words: OrigWord[];
  /** Indices of words that are Aramaic (Dan 2:4b–7:28, Ezra 4:8–6:18, 7:12–26, Jer 10:11, Gen 31:47). Omitted if none. */
  aramaic?: number[];
}

/* ------------------------------------------------------------------------ */
/* Translation text: public/data/text/{TR}/{BOOK}/{CHAPTER}.json            */
/* ------------------------------------------------------------------------ */

/** Extra per-word information, only present when needed. */
export interface TokenInfo {
  /** Strong's ids carried by the translation's own tagging that could NOT be linked to a word in OrigChapter (e.g. KJV words from the Textus Receptus absent in SBLGNT). */
  s?: string[];
  /** Morphology codes paired with `s` (same length) when known. */
  m?: string[];
  /** Original-language surface forms paired with `s` when known (e.g. the KJV's TR form). */
  o?: string[];
  /** Alignment confidence 0–1 for 'bridged' alignments (omitted = 1). */
  c?: number;
  /** 1 = word supplied by the translators (KJV italics); no original word behind it. */
  i?: 1;
}

/**
 * A rendered piece of verse text.
 *  - string: literal text that is not linked (spaces, punctuation, and words with no original-language link).
 *  - WordToken: one English word linked to one or more original words.
 *
 * Concatenating every token's text reproduces the verse exactly.
 */
export type Token = string | WordToken;

/** [english word, indices into OrigChapter.words, optional info] */
export type WordToken = [text: string, links: number[], info?: TokenInfo];

export interface TextVerse {
  /** Verse number. */
  v: number;
  /** Tokens in reading order. */
  t: Token[];
}

export interface TextChapter {
  /** Translation id, e.g. "BSB". */
  tr: string;
  book: BookId;
  chapter: number;
  verses: TextVerse[];
  /** Section headings: [verse the heading precedes, heading text]. */
  headings?: [number, string][];
  /** Verse numbers that begin a new paragraph (verse 1 is implied). */
  paras?: number[];
  /**
   * Psalm title / superscription shown before verse 1, when it is not numbered as a verse in this
   * translation. Tokens may link to OrigChapter.words just like verse tokens (Hebrew numbers the
   * title as verse 1, so those words live in this chapter's OrigChapter with OW.verse = 0).
   */
  superscription?: Token[];
}

/* ------------------------------------------------------------------------ */
/* Lexicon: public/data/lex/{G|H}/{NNN}.json                                */
/* ------------------------------------------------------------------------ */

/**
 * Chunk file NNN holds every entry whose Strong's number n satisfies floor(n / 100) == NNN
 * (zero-padded to 3 digits). E.g. G0026 -> lex/G/000.json, H7225 -> lex/H/072.json.
 * Keys are normalised ids including any extension letter ("H0871a"); a base id
 * ("H0871") is also present whenever any entry exists for that number.
 */
export type LexChunk = Record<string, LexEntry>;

export interface LexEntry {
  /** Normalised Strong's id, e.g. "G0026". */
  id: string;
  /** Dictionary form in the original script. */
  lemma: string;
  /** Transliteration of the lemma, e.g. "agapē". */
  translit: string;
  /** Human-readable part of speech, e.g. "Noun, feminine", "Verb". */
  pos: string;
  /** Short gloss, e.g. "love". */
  gloss: string;
  /** Brief definition (STEPBible: Abbott-Smith for Greek, abridged BDB for Hebrew). Sanitised HTML: only <b>, <i>, <br>, <span class="ref"> allowed. */
  def: string;
  /** Strong's own definition (public domain). */
  strongsDef?: string;
  /** How the KJV renders the word ("KJV usage"). */
  kjv?: string;
  /** Strong's derivation note. */
  deriv?: string;
}

/* ------------------------------------------------------------------------ */
/* Concordance: public/data/conc/{G|H}/{NNN}.json                           */
/* ------------------------------------------------------------------------ */

/**
 * Same chunking as the lexicon. Maps a Strong's id (base id, no extension letter)
 * to the sorted, de-duplicated list of English-versification verses where it occurs.
 * A verse ref is packed as  bookNum * 1_000_000 + chapter * 1_000 + verse.
 */
export type ConcChunk = Record<string, number[]>;

/* ------------------------------------------------------------------------ */
/* Search corpus: public/data/search/{TR}.json                              */
/* ------------------------------------------------------------------------ */

export interface SearchCorpus {
  tr: string;
  /** Every verse: [bookNum (1-66), chapter, verse, plain text]. Canonical order. */
  verses: [number, number, number, string][];
}

/* ------------------------------------------------------------------------ */
/* Runtime helpers shared by UI code                                         */
/* ------------------------------------------------------------------------ */

export interface VerseRef {
  book: BookId;
  chapter: number;
  /** Optional single verse or start of a range. */
  verse?: number;
  /** Optional end of a range (same chapter). */
  verseEnd?: number;
}

export const packRef = (bookNum: number, chapter: number, verse: number): number =>
  bookNum * 1_000_000 + chapter * 1_000 + verse;

export const unpackRef = (packed: number): { bookNum: number; chapter: number; verse: number } => ({
  bookNum: Math.floor(packed / 1_000_000),
  chapter: Math.floor((packed % 1_000_000) / 1_000),
  verse: packed % 1_000,
});
